        dx += (vec_lo(v->s[5]) - dx) >> (fast ? 2 : 5);
        dy += (vec_hi(v->s[5]) - dy) >> (fast ? 2 : 5);
        v->s[4] = vec_pk(dx, dy);
        break;
    default:
