static void *eng_arena_of(const track_t *t, uint32_t eng)
{
    uint32_t p = (uint32_t)(t - PKV(4));
    if (p >= 3)
        return 0;
    if (PKV(63)[p] != eng + 1u) {
        memset(&PKV(62)[p], 0, sizeof PKV(62)[p]);
        PKV(63)[p] = (uint8_t)(eng + 1u);
    }
    return &PKV(62)[p];
}
