/* (eng_wave.c) the table of the instrument: track 1's, else its layer's (one table in RAM: two WAVE sounds share
 * track 1's); while a sound fades out after a change (voice.c sound_fade_begin) its table stays */
static int32_t wt_wanted(void)
{
    uint32_t k;
    for (k = 0; k < 2u; k++) {
        const track_t *t = &PKV(4)[k];
        if (k && (t->p[P_SSWING] != LY_LAYER && t->p[P_SSWING] != LY_SPLIT && t->p[P_SSWING] != LY_MULTI))
            break;
        if (t->xf_on && ENGINES[t->engine % (13 + 10)] == &ENG_WAVE)
            return PKV(46);
        if (ENGINES[t->eng_req % (13 + 10)] == &ENG_WAVE)
            return PKV(47)[k] ? PKV(47)[k] - 1 : (int32_t)((uint32_t)t->p[P_E0] % (16 + 4)); /* (0.9: after the duck) */
    }
    return -1;
}
