static int16_t preset_trim(uint32_t e, uint32_t pi)
{
    if (1 && (ENGINES[e % (13 + 10)] == &ENG_SAMPLE || ENGINES[e % (13 + 10)] == &ENG_GRAIN))
        return 0; /* (Clipper: the user's own samples, no factory level) */
    if (e >= 0u) /* Clipper's own engines: their table (preset_trim_clipper.h) */
        return e - 0u < 23u && pi < 32u ? PRESET_TRIM_CL[e - 0u][pi] : 0;
    return e < 13u && pi < 32u ? PRESET_TRIM[e][pi] : 0;
}
