    mb = ((673 << 8) + ((osc_sine(PKV(148).lph + 0x40000000u) * 12) >> 7));
    a = pl_mod_ap(PL_MA, x + mulq15(PKV(148).end[1], decay), -22938, ma); /* -0.7: the decay diffusion */
    b = pl_mod_ap(PL_MB, x + mulq15(PKV(148).end[0], decay), -22938, mb);
    pl_put(PL_DA1, a);
    pl_put(PL_DB1, b);
