    b = pl_tap(PL_DB1, PL_LEN[PL_DB1]);
    PKV(148).dmp[0] += mulq15(a - PKV(148).dmp[0], damp);
    PKV(148).dmp[1] += mulq15(b - PKV(148).dmp[1], damp);
    a = pl_ap(PL_AA, mulq15(PKV(148).dmp[0], decay), 16384); /* 0.5 */
    b = pl_ap(PL_AB, mulq15(PKV(148).dmp[1], decay), 16384);
    pl_put(PL_DA2, a);
    pl_put(PL_DB2, b);
    PKV(148).end[0] = pl_tap(PL_DA2, PL_LEN[PL_DA2]);
    PKV(148).end[1] = pl_tap(PL_DB2, PL_LEN[PL_DB2]);
