        return;
    if (fm1_usb_sof_take()) { /* SOF pending: not a reliable "host is there", */
                                                        /* it keeps firing with the cable out */
        PKV(183).sof_seen++;
        PKV(183).no_sof = 0;
    } else if (++PKV(183).no_sof > PKV(183).max_gap) {
        PKV(183).max_gap = PKV(183).no_sof;
    }
    if (PKV(183).config) { /* the frame number only advances with a real host */
        /* (statics: hoisted) */
        if (++PKV(191) >= 20u) { /* every 20 polls = 10 ms */
            uint16_t f;
            PKV(191) = 0;
            f = (uint16_t)(sie_rd(S_FRAME1) | (sie_rd(S_FRAME2) & 7u) << 8);
            if (f != PKV(183).frame) {
                PKV(183).frame = f;
                PKV(183).frame_same = 0;
                PKV(183).suspended = 0;
            } else if (++PKV(183).frame_same >= 10u && !PKV(183).suspended) { /* 100 ms frozen: unplugged / host asleep */
                PKV(183).suspended = 1;
                PKV(183).frame_stalls++;
            }
        }
    }
    iu = sie_rd(S_INTRUSB);
    it = sie_rd(S_INTRTX1); /* EP0..7 only: skipping INTR*2 saves */
    ir = sie_rd(S_INTRRX1); /* 2 SIE round trips per poll */
