    m = DIV_BEATS[(div - 6u) % 3u]; /* whole beats: the step from the beat count */
    return grid_swing(PKV(6) / m, (PKV(6) % m) * ((uint32_t)44100 * 60u) + PKV(7), ((uint32_t)44100 * 60u) * m, sw, into, len);
